import { useState, useRef, useEffect } from "react";
import { db } from "../../firebaseConfig";
import { ref, onValue, set, off, get } from "firebase/database";
import "./regStyles.css";

const Reglement = (props) => {
  const [isEditing, setIsEditing] = useState(false);
  const contentRef = useRef(null);
  const [content, setContent] = useState("");

  useEffect(() => {
    const dbRef = ref(db, "regler/0");

    const handleDataChange = (snapshot) => {
      if (snapshot && snapshot.val() && snapshot.val().text) {
        setContent(snapshot.val().text);
      }
    };

    onValue(dbRef, handleDataChange);

    // Cleanup
    return () => {
      off(dbRef, handleDataChange);
    };
  }, []);

  const saveContent = async () => {
    const newContent = contentRef.current.innerHTML;
    setIsEditing(false);

    // Update the content state immediately
    setContent(newContent);

    // Update the content in the database
    await updateContent(newContent);
  };

  const updateContent = async (newContent) => {
    try {
      await set(ref(db, "regler/0"), { text: newContent });
      console.log("Content saved:", newContent);
    } catch (error) {
      console.error("Error saving content:", error);
    }
  };

  const insertElements = () => {
    const currentHTML = contentRef.current.innerHTML;
    const newHTML = `
      ${currentHTML}
      <h2>§ New Paragraph</h1>
      <p>New Paragraph</p>
      <ul>
        <li>Bullet Point 1</li>
      </ul>
    `;
    contentRef.current.innerHTML = newHTML;
  };

const saveNewRule = async (newContent) => {
  try {
    const rulesRef = ref(db, "regler/1"); // Reference to 'regler/1' node where rules are stored
    const snapshot = await get(rulesRef); // Fetch existing rules from regler/1

    const existingRules = snapshot.exists() ? snapshot.val() : []; // Get the list or initialize it as empty
    const updatedRules = [...existingRules, { text: newContent }]; // Append the new rule

    // Save the updated list back to 'regler/1'
    await set(rulesRef, updatedRules); 
    console.log("Content appended to regler/1:", newContent);
  } catch (error) {
    console.error("Error appending content:", error);
  }
};

  return (
    <>
                {props.botsjef && (
              <button onClick={() => setIsEditing(true)}>Rediger</button>
            )}
      <div className="reglement">
        {isEditing ? (
          <div>
            <div
              ref={contentRef}
              contentEditable={true}
              dangerouslySetInnerHTML={{ __html: content }}
            />
            <button onClick={saveContent}>Save</button>
            {isEditing && (
              <>
              <button onClick={insertElements}>legg til paragraf</button>
              <button onClick={saveNewRule}>legg til paragraf i systemet</button>
              <input id="newRule" placeholder="§ 3 Forfall til trening (1-3)"></input>
              </>
            )}
          </div>
        ) : (
          <div>
            <div dangerouslySetInnerHTML={{ __html: content }} />
            {props.botsjef && (
              <button onClick={() => setIsEditing(true)}>Rediger</button>
            )}
          </div>
        )}
      </div>
    </>
  );
};

export default Reglement;
